-- StockSense: complete database setup for a NEW Supabase project.
-- Generated by `npm run bundle` in supabase/tests. Do not edit by hand;
-- change the files in supabase/migrations and supabase/seed.sql instead.

-- ===== 20260926000001_schema.sql =====
-- StockSense schema: master data, stock, operations and the append-only ledger.
-- Quantities use numeric(15,3) so kg / litres work as well as pieces.

-- ---------------------------------------------------------------------------
-- Enums
-- ---------------------------------------------------------------------------
create type public.app_role as enum ('MANAGER', 'STAFF');

-- INTERNAL = a real place that holds stock; the other three are virtual
-- counterparts so every stock change can be written as "from -> to".
create type public.location_type as enum ('INTERNAL', 'VENDOR', 'CUSTOMER', 'INVENTORY_LOSS');

create type public.operation_type as enum ('RECEIPT', 'DELIVERY', 'TRANSFER', 'ADJUSTMENT');

create type public.operation_state as enum ('DRAFT', 'WAITING', 'READY', 'DONE', 'CANCELLED');

create type public.move_type as enum ('INITIAL', 'RECEIPT', 'DELIVERY', 'TRANSFER', 'ADJUSTMENT');

-- ---------------------------------------------------------------------------
-- Shared trigger: keep updated_at current
-- ---------------------------------------------------------------------------
create function public.set_updated_at()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- Warehouses and locations
-- ---------------------------------------------------------------------------
create table public.warehouses (
  id             bigint generated always as identity primary key,
  name           text not null check (length(trim(name)) > 0),
  code           text not null check (length(trim(code)) > 0),
  address        text not null default '',
  capacity_units numeric(15,3) check (capacity_units is null or capacity_units > 0),
  active         boolean not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create unique index warehouses_name_key on public.warehouses (lower(name));
create unique index warehouses_code_key on public.warehouses (upper(code));
create trigger warehouses_updated_at before update on public.warehouses
  for each row execute function public.set_updated_at();

create table public.locations (
  id           bigint generated always as identity primary key,
  warehouse_id bigint references public.warehouses (id) on delete restrict,
  name         text not null check (length(trim(name)) > 0),
  code         text not null,
  type         public.location_type not null,
  is_default   boolean not null default false,
  active       boolean not null default true,
  created_at   timestamptz not null default now(),
  -- Real locations belong to a warehouse; virtual ones never do.
  constraint locations_internal_has_warehouse
    check ((type = 'INTERNAL') = (warehouse_id is not null))
);
create unique index locations_code_key on public.locations (upper(code));
create unique index locations_warehouse_name_key on public.locations (warehouse_id, lower(name))
  where warehouse_id is not null;
create unique index locations_one_default_per_warehouse on public.locations (warehouse_id)
  where is_default;
-- Exactly one Vendors / Customers / Inventory Adjustment location.
create unique index locations_one_per_virtual_type on public.locations (type)
  where warehouse_id is null;

-- ---------------------------------------------------------------------------
-- Users (1:1 with auth.users)
-- ---------------------------------------------------------------------------
create table public.profiles (
  id                   uuid primary key references auth.users (id) on delete cascade,
  full_name            text not null default '',
  email                text not null default '',
  role                 public.app_role not null default 'STAFF',
  job_title            text not null default '',
  default_warehouse_id bigint references public.warehouses (id) on delete set null,
  active               boolean not null default true,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);
create trigger profiles_updated_at before update on public.profiles
  for each row execute function public.set_updated_at();

-- Every new auth user gets a profile. The very first one becomes MANAGER.
create function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_role public.app_role := 'STAFF';
begin
  -- Serialise concurrent sign-ups so two people can't both be "first".
  perform pg_advisory_xact_lock(hashtext('stocksense.first_user'));
  if not exists (select 1 from public.profiles) then
    v_role := 'MANAGER';
  end if;

  insert into public.profiles (id, email, full_name, role, job_title, default_warehouse_id)
  values (
    new.id,
    coalesce(new.email, ''),
    coalesce(nullif(trim(new.raw_user_meta_data ->> 'full_name'), ''), split_part(coalesce(new.email, ''), '@', 1)),
    v_role,
    case when v_role = 'MANAGER' then 'Inventory Manager' else 'Warehouse Staff' end,
    -- app_settings is created later in the migrations, so look it up defensively.
    (select s.default_warehouse_id from public.app_settings s where s.id = 1)
  );
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------------------
-- Catalogue
-- ---------------------------------------------------------------------------
create table public.categories (
  id         bigint generated always as identity primary key,
  name       text not null check (length(trim(name)) > 0),
  color      text not null default '#64748b' check (color ~ '^#[0-9a-fA-F]{6}$'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index categories_name_key on public.categories (lower(name));
create trigger categories_updated_at before update on public.categories
  for each row execute function public.set_updated_at();

create sequence public.product_sku_seq;

create table public.products (
  id                   bigint generated always as identity primary key,
  name                 text not null check (length(trim(name)) > 0),
  sku                  text not null check (length(trim(sku)) > 0),
  category_id          bigint not null references public.categories (id) on delete restrict,
  unit                 text not null default 'pcs' check (length(trim(unit)) > 0),
  price                numeric(15,2) not null default 0 check (price >= 0),
  primary_warehouse_id bigint references public.warehouses (id) on delete set null,
  archived             boolean not null default false,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);
-- SKUs are unique regardless of case.
create unique index products_sku_key on public.products (upper(sku));
create index products_category_idx on public.products (category_id);
create index products_name_idx on public.products (lower(name));

-- Store SKUs trimmed and upper-case so lookups are predictable.
create function public.normalize_product()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  new.sku  := upper(trim(new.sku));
  new.name := trim(new.name);
  new.unit := trim(new.unit);
  return new;
end;
$$;
create trigger products_normalize before insert or update on public.products
  for each row execute function public.normalize_product();
create trigger products_updated_at before update on public.products
  for each row execute function public.set_updated_at();

create table public.reorder_rules (
  product_id  bigint primary key references public.products (id) on delete cascade,
  min_qty     numeric(15,3) not null default 0 check (min_qty >= 0),
  reorder_qty numeric(15,3) check (reorder_qty is null or reorder_qty > 0),
  updated_at  timestamptz not null default now()
);
create trigger reorder_rules_updated_at before update on public.reorder_rules
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Stock on hand: one row per product per INTERNAL location.
-- Only the stock engine functions write here.
-- ---------------------------------------------------------------------------
create table public.stock_quants (
  product_id  bigint not null references public.products (id) on delete restrict,
  location_id bigint not null references public.locations (id) on delete restrict,
  quantity    numeric(15,3) not null default 0,
  updated_at  timestamptz not null default now(),
  primary key (product_id, location_id),
  -- Last line of defence: stock in a real place can never go negative.
  constraint stock_quants_non_negative check (quantity >= 0)
);
create index stock_quants_location_idx on public.stock_quants (location_id);

-- ---------------------------------------------------------------------------
-- Operation documents (receipts, deliveries, transfers, adjustments)
-- ---------------------------------------------------------------------------
create table public.operations (
  id                      bigint generated always as identity primary key,
  reference               text not null unique,
  type                    public.operation_type not null,
  state                   public.operation_state not null default 'DRAFT',
  source_location_id      bigint not null references public.locations (id),
  destination_location_id bigint not null references public.locations (id),
  partner_name            text not null default '',
  reason                  text not null default '',
  notes                   text not null default '',
  scheduled_date          date,
  responsible_id          uuid references public.profiles (id) on delete set null,
  -- Name snapshot so the history still reads correctly if a user is removed.
  responsible_name        text not null default '',
  created_by              uuid references public.profiles (id) on delete set null,
  backorder_of_id         bigint references public.operations (id),
  validated_at            timestamptz,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),
  constraint operations_distinct_locations check (source_location_id <> destination_location_id)
);
create index operations_type_state_idx on public.operations (type, state);
create index operations_created_at_idx on public.operations (created_at desc);
create index operations_scheduled_idx on public.operations (scheduled_date);
create trigger operations_updated_at before update on public.operations
  for each row execute function public.set_updated_at();

create table public.operation_lines (
  id               bigint generated always as identity primary key,
  operation_id     bigint not null references public.operations (id) on delete cascade,
  product_id       bigint not null references public.products (id),
  -- Planned quantity. For adjustments it becomes |counted - system| on validation.
  quantity         numeric(15,3) not null default 0 check (quantity >= 0),
  done_quantity    numeric(15,3) not null default 0 check (done_quantity >= 0),
  -- Adjustments only: what was physically counted, and what the system said.
  counted_quantity numeric(15,3) check (counted_quantity is null or counted_quantity >= 0),
  system_quantity  numeric(15,3),
  constraint operation_lines_one_row_per_product unique (operation_id, product_id)
);
create index operation_lines_product_idx on public.operation_lines (product_id);

-- ---------------------------------------------------------------------------
-- Ledger: every stock change, never edited or deleted.
-- ---------------------------------------------------------------------------
create table public.stock_moves (
  id                      bigint generated always as identity primary key,
  operation_id            bigint references public.operations (id),
  operation_line_id       bigint references public.operation_lines (id),
  product_id              bigint not null references public.products (id),
  source_location_id      bigint not null references public.locations (id),
  destination_location_id bigint not null references public.locations (id),
  quantity                numeric(15,3) not null check (quantity > 0),
  move_type               public.move_type not null,
  reference               text not null,
  -- No FK on purpose: removing a user must never require editing the ledger.
  performed_by            uuid,
  performed_by_name       text not null default '',
  performed_at            timestamptz not null default now(),
  constraint stock_moves_distinct_locations check (source_location_id <> destination_location_id)
);
create index stock_moves_product_time_idx on public.stock_moves (product_id, performed_at);
create index stock_moves_time_idx on public.stock_moves (performed_at);
create index stock_moves_operation_idx on public.stock_moves (operation_id);

create function public.prevent_ledger_change()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  raise exception 'stock_moves is append-only; record a new adjustment instead'
    using errcode = 'PT409';
end;
$$;
create trigger stock_moves_no_update before update or delete on public.stock_moves
  for each row execute function public.prevent_ledger_change();
create trigger stock_moves_no_truncate before truncate on public.stock_moves
  for each statement execute function public.prevent_ledger_change();

-- ---------------------------------------------------------------------------
-- Gap-free document numbers per prefix and year (PO-2026-0001 ...)
-- ---------------------------------------------------------------------------
create table public.reference_sequences (
  prefix     text not null,
  year       int  not null,
  next_value int  not null default 1,
  primary key (prefix, year)
);

-- ---------------------------------------------------------------------------
-- App settings (single row)
-- ---------------------------------------------------------------------------
create table public.app_settings (
  id                                   smallint primary key default 1 check (id = 1),
  workspace_name                       text not null default 'StockSense',
  default_warehouse_id                 bigint references public.warehouses (id) on delete set null,
  reorder_multiplier                   int not null default 3 check (reorder_multiplier in (2, 3, 5)),
  require_signoff_negative_adjustments boolean not null default true,
  stock_target_units                   numeric(15,3) check (stock_target_units is null or stock_target_units > 0),
  time_zone                            text not null default 'Asia/Kolkata',
  updated_at                           timestamptz not null default now()
);
create trigger app_settings_updated_at before update on public.app_settings
  for each row execute function public.set_updated_at();

-- ===== 20260926000002_security.sql =====
-- Row Level Security.
-- Rules (from the product brief):
--   * Everyone signed in (and active) can read everything.
--   * MANAGER edits master data (warehouses, locations, categories, products, settings).
--   * Stock tables and operation documents are never written directly by clients;
--     they change only through the SECURITY DEFINER functions in the stock engine.
--   * Anonymous visitors see nothing.

-- ---------------------------------------------------------------------------
-- Helpers used by policies and functions
-- ---------------------------------------------------------------------------
create function public.is_active_user()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (select 1 from public.profiles where id = auth.uid() and active);
$$;

create function public.is_manager()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce((select role = 'MANAGER' from public.profiles where id = auth.uid() and active), false);
$$;

-- ---------------------------------------------------------------------------
-- Enable RLS everywhere
-- ---------------------------------------------------------------------------
alter table public.warehouses          enable row level security;
alter table public.locations           enable row level security;
alter table public.profiles            enable row level security;
alter table public.categories          enable row level security;
alter table public.products            enable row level security;
alter table public.reorder_rules       enable row level security;
alter table public.stock_quants        enable row level security;
alter table public.operations          enable row level security;
alter table public.operation_lines     enable row level security;
alter table public.stock_moves         enable row level security;
alter table public.reference_sequences enable row level security;
alter table public.app_settings        enable row level security;

-- ---------------------------------------------------------------------------
-- Read access: any active signed-in user
-- (select ...) wrappers let Postgres evaluate the helper once per query.
-- ---------------------------------------------------------------------------
create policy "active users can read" on public.warehouses      for select to authenticated using ((select public.is_active_user()));
create policy "active users can read" on public.locations       for select to authenticated using ((select public.is_active_user()));
create policy "active users can read" on public.profiles        for select to authenticated using ((select public.is_active_user()) or id = (select auth.uid()));
create policy "active users can read" on public.categories      for select to authenticated using ((select public.is_active_user()));
create policy "active users can read" on public.products        for select to authenticated using ((select public.is_active_user()));
create policy "active users can read" on public.reorder_rules   for select to authenticated using ((select public.is_active_user()));
create policy "active users can read" on public.stock_quants    for select to authenticated using ((select public.is_active_user()));
create policy "active users can read" on public.operations      for select to authenticated using ((select public.is_active_user()));
create policy "active users can read" on public.operation_lines for select to authenticated using ((select public.is_active_user()));
create policy "active users can read" on public.stock_moves     for select to authenticated using ((select public.is_active_user()));
create policy "active users can read" on public.app_settings    for select to authenticated using ((select public.is_active_user()));
-- reference_sequences: no policies at all -> only the engine touches it.

-- ---------------------------------------------------------------------------
-- Master data writes: managers only
-- (Creating products and warehouses normally goes through RPCs so that
--  initial stock and default locations are created in the same transaction.)
-- ---------------------------------------------------------------------------
create policy "managers can insert" on public.categories for insert to authenticated with check ((select public.is_manager()));
create policy "managers can update" on public.categories for update to authenticated using ((select public.is_manager())) with check ((select public.is_manager()));

create policy "managers can update" on public.products for update to authenticated using ((select public.is_manager())) with check ((select public.is_manager()));

create policy "managers can insert" on public.reorder_rules for insert to authenticated with check ((select public.is_manager()));
create policy "managers can update" on public.reorder_rules for update to authenticated using ((select public.is_manager())) with check ((select public.is_manager()));
create policy "managers can delete" on public.reorder_rules for delete to authenticated using ((select public.is_manager()));

create policy "managers can update" on public.warehouses for update to authenticated using ((select public.is_manager())) with check ((select public.is_manager()));
create policy "managers can update" on public.locations  for update to authenticated using ((select public.is_manager())) with check ((select public.is_manager()));

create policy "managers can update" on public.app_settings for update to authenticated using ((select public.is_manager())) with check ((select public.is_manager()));

-- Users may edit their own profile (columns limited by the grants below).
create policy "users can update own profile" on public.profiles
  for update to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

-- ---------------------------------------------------------------------------
-- Table privileges (defence in depth on top of RLS)
-- ---------------------------------------------------------------------------
revoke all on all tables in schema public from anon;

-- Profiles: only the harmless columns are self-editable; role/active change via RPC.
revoke insert, update, delete, truncate on public.profiles from authenticated;
grant update (full_name, job_title, default_warehouse_id) on public.profiles to authenticated;

-- Stock and documents: read-only for clients.
revoke insert, update, delete, truncate on public.stock_quants    from authenticated;
revoke insert, update, delete, truncate on public.stock_moves     from authenticated;
revoke insert, update, delete, truncate on public.operations      from authenticated;
revoke insert, update, delete, truncate on public.operation_lines from authenticated;
revoke all on public.reference_sequences from authenticated;

-- Deleting master data is not allowed (products are archived instead).
revoke delete, truncate on public.products, public.categories, public.warehouses, public.locations, public.app_settings from authenticated;

-- ===== 20260926000003_views.sql =====
-- Read models shaped like the frontend's mock data (mockProducts, mockOperations,
-- mockWarehouses). All views use security_invoker so the caller's RLS applies.

-- ---------------------------------------------------------------------------
-- Display helpers
-- ---------------------------------------------------------------------------
create function public.app_time_zone()
returns text
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce((select time_zone from public.app_settings where id = 1), 'Asia/Kolkata');
$$;

-- The UI shows "2026-09-26 10:45" (no seconds, local time).
create function public.display_time(p_ts timestamptz)
returns text
language sql
stable
set search_path = public, pg_temp
as $$
  select to_char(p_ts at time zone public.app_time_zone(), 'YYYY-MM-DD HH24:MI');
$$;

create function public.operation_label(p_type public.operation_type)
returns text
language sql
immutable
set search_path = public, pg_temp
as $$
  select case p_type
    when 'RECEIPT'    then 'Receipt'
    when 'DELIVERY'   then 'Delivery'
    when 'TRANSFER'   then 'Internal Transfer'
    when 'ADJUSTMENT' then 'Adjustment'
  end;
$$;

create function public.move_label(p_type public.move_type)
returns text
language sql
immutable
set search_path = public, pg_temp
as $$
  select case p_type
    when 'INITIAL'    then 'Initial Stock'
    when 'RECEIPT'    then 'Receipt'
    when 'DELIVERY'   then 'Delivery'
    when 'TRANSFER'   then 'Internal Transfer'
    when 'ADJUSTMENT' then 'Adjustment'
  end;
$$;

-- The UI knows four statuses; the engine has five (DRAFT and WAITING both read "Pending").
create function public.status_label(p_state public.operation_state)
returns text
language sql
immutable
set search_path = public, pg_temp
as $$
  select case p_state
    when 'DRAFT'     then 'Pending'
    when 'WAITING'   then 'Pending'
    when 'READY'     then 'In Progress'
    when 'DONE'      then 'Completed'
    when 'CANCELLED' then 'Cancelled'
  end;
$$;

-- "Low Stock" uses <= because the Low Stock page says "inventory <= safety reorder point".
create function public.stock_status(p_stock numeric, p_min numeric)
returns text
language sql
immutable
set search_path = public, pg_temp
as $$
  select case
    when p_stock <= 0 then 'Out of Stock'
    when p_min > 0 and p_stock <= p_min then 'Low Stock'
    else 'In Stock'
  end;
$$;

-- ---------------------------------------------------------------------------
-- Locations with a human label ("Main Central Hub", "Main Central Hub / Production Rack")
-- ---------------------------------------------------------------------------
create view public.v_locations
with (security_invoker = true) as
select
  l.id,
  l.name,
  l.code,
  l.type,
  l.warehouse_id,
  coalesce(w.name, '') as warehouse,
  l.is_default,
  l.active,
  case
    when l.warehouse_id is null then l.name
    when l.is_default then w.name
    else w.name || ' / ' || l.name
  end as label
from public.locations l
left join public.warehouses w on w.id = l.warehouse_id;

-- ---------------------------------------------------------------------------
-- Products (mockProducts shape). Pass a warehouse id to scope the stock figure.
-- ---------------------------------------------------------------------------
create function public.product_rows(p_warehouse_id bigint default null)
returns table (
  id           bigint,
  name         text,
  sku          text,
  category     text,
  category_id  bigint,
  stock        numeric,
  min_stock    numeric,
  reorder_qty  numeric,
  price        numeric,
  unit         text,
  warehouse    text,
  warehouse_id bigint,
  status       text,
  archived     boolean,
  created_at   timestamptz
)
language sql
stable
set search_path = public, pg_temp
as $$
  select
    p.id,
    p.name,
    p.sku,
    c.name,
    p.category_id,
    coalesce(s.qty, 0),
    coalesce(r.min_qty, 0),
    r.reorder_qty,
    p.price,
    p.unit,
    coalesce(w.name, ''),
    p.primary_warehouse_id,
    public.stock_status(coalesce(s.qty, 0), coalesce(r.min_qty, 0)),
    p.archived,
    p.created_at
  from public.products p
  join public.categories c on c.id = p.category_id
  left join public.reorder_rules r on r.product_id = p.id
  left join public.warehouses w on w.id = p.primary_warehouse_id
  left join lateral (
    select sum(q.quantity) as qty
    from public.stock_quants q
    join public.locations l on l.id = q.location_id
    where q.product_id = p.id
      and l.type = 'INTERNAL'
      and (p_warehouse_id is null or l.warehouse_id = p_warehouse_id)
  ) s on true;
$$;

create view public.v_product_rows
with (security_invoker = true) as
select * from public.product_rows(null);

-- Stock per product per location (product detail, operation forms).
create view public.v_stock_levels
with (security_invoker = true) as
select
  q.product_id,
  p.name as product,
  p.sku,
  p.unit,
  q.location_id,
  l.label as location,
  l.warehouse_id,
  l.warehouse,
  q.quantity
from public.stock_quants q
join public.products p on p.id = q.product_id
join public.v_locations l on l.id = q.location_id
where q.quantity > 0;

-- ---------------------------------------------------------------------------
-- Warehouses (mockWarehouses shape)
-- ---------------------------------------------------------------------------
create view public.v_warehouse_cards
with (security_invoker = true) as
select
  w.id,
  w.name,
  w.code,
  w.address as location,
  coalesce(t.total, 0) as total_items,
  w.capacity_units,
  case when w.capacity_units is null then null
       else round(coalesce(t.total, 0) / w.capacity_units * 100, 1) end as capacity_percent,
  -- The UI needs a string like "88%" (it uses it as a CSS width).
  (case when w.capacity_units is null then 0
        else round(coalesce(t.total, 0) / w.capacity_units * 100) end)::int::text || '%' as capacity,
  coalesce(m.cnt, 0)::int as active_managers,
  w.active,
  w.created_at
from public.warehouses w
left join lateral (
  select sum(q.quantity) as total
  from public.stock_quants q
  join public.locations l on l.id = q.location_id
  where l.warehouse_id = w.id
) t on true
left join lateral (
  select count(*) as cnt
  from public.profiles pr
  where pr.default_warehouse_id = w.id and pr.active
) m on true;

-- ---------------------------------------------------------------------------
-- Operation documents (header only, with labels)
-- ---------------------------------------------------------------------------
create view public.v_operation_documents
with (security_invoker = true) as
select
  o.id,
  o.reference,
  o.type,
  public.operation_label(o.type) as operation,
  o.state,
  public.status_label(o.state) as status,
  o.source_location_id,
  src.label as source,
  src.type as source_type,
  src.warehouse_id as source_warehouse_id,
  o.destination_location_id,
  dst.label as destination,
  dst.type as destination_type,
  dst.warehouse_id as destination_warehouse_id,
  o.partner_name,
  o.reason,
  o.notes,
  o.scheduled_date,
  o.responsible_id,
  o.responsible_name as responsible,
  o.backorder_of_id,
  coalesce(bo.reference, '') as backorder_of,
  (select count(*) from public.operation_lines x where x.operation_id = o.id)::int as line_count,
  public.display_time(coalesce(o.validated_at, o.created_at)) as date,
  coalesce(o.validated_at, o.created_at) as date_iso,
  o.created_at,
  o.validated_at
from public.operations o
join public.v_locations src on src.id = o.source_location_id
join public.v_locations dst on dst.id = o.destination_location_id
left join public.operations bo on bo.id = o.backorder_of_id;

-- ---------------------------------------------------------------------------
-- Operation rows: one row per document line (mockOperations shape).
-- quantity is signed: + into stock, - out of stock.
-- ---------------------------------------------------------------------------
create view public.v_operation_rows
with (security_invoker = true) as
select
  ln.id,
  d.id as document_id,
  ln.product_id,
  p.name as product,
  p.sku,
  d.operation,
  d.type,
  d.state,
  d.status,
  case d.type
    when 'RECEIPT'  then d.destination
    when 'TRANSFER' then d.source || ' -> ' || d.destination
    else d.source
  end as warehouse,
  case d.type
    -- Adjustments show the difference; before validation, against current stock.
    when 'ADJUSTMENT' then coalesce(ln.counted_quantity, 0) - coalesce(ln.system_quantity, cur.quantity, 0)
    when 'DELIVERY'   then -(case when d.state = 'DONE' then ln.done_quantity else ln.quantity end)
    else                   (case when d.state = 'DONE' then ln.done_quantity else ln.quantity end)
  end as quantity,
  ln.quantity as planned_quantity,
  ln.done_quantity,
  ln.counted_quantity,
  ln.system_quantity,
  p.unit,
  d.date,
  d.date_iso,
  d.responsible,
  d.reference,
  d.partner_name,
  d.scheduled_date,
  d.source_warehouse_id,
  d.destination_warehouse_id,
  d.created_at
from public.operation_lines ln
join public.v_operation_documents d on d.id = ln.operation_id
join public.products p on p.id = ln.product_id
left join public.stock_quants cur
  on cur.product_id = ln.product_id and cur.location_id = d.source_location_id;

-- ---------------------------------------------------------------------------
-- Ledger rows (the Stock Ledger page): completed moves only.
-- ---------------------------------------------------------------------------
create view public.v_ledger_rows
with (security_invoker = true) as
select
  m.id,
  m.move_type as type,
  public.move_label(m.move_type) as operation,
  m.product_id,
  p.name as product,
  p.sku,
  case
    when src.type = 'INTERNAL' and dst.type = 'INTERNAL' then src.label || ' -> ' || dst.label
    when dst.type = 'INTERNAL' then dst.label
    else src.label
  end as warehouse,
  case
    when src.type <> 'INTERNAL' and dst.type = 'INTERNAL' then m.quantity
    when src.type = 'INTERNAL' and dst.type <> 'INTERNAL' then -m.quantity
    else m.quantity
  end as quantity,
  p.unit,
  'Completed'::text as status,
  public.display_time(m.performed_at) as date,
  m.performed_at as date_iso,
  m.performed_by_name as responsible,
  m.reference,
  src.label as source_location,
  dst.label as destination_location,
  src.warehouse_id as source_warehouse_id,
  dst.warehouse_id as destination_warehouse_id,
  m.operation_id as document_id,
  m.performed_at
from public.stock_moves m
join public.products p on p.id = m.product_id
join public.v_locations src on src.id = m.source_location_id
join public.v_locations dst on dst.id = m.destination_location_id;

revoke all on public.v_locations, public.v_product_rows, public.v_stock_levels,
  public.v_warehouse_cards, public.v_operation_documents, public.v_operation_rows,
  public.v_ledger_rows from anon;
grant select on public.v_locations, public.v_product_rows, public.v_stock_levels,
  public.v_warehouse_cards, public.v_operation_documents, public.v_operation_rows,
  public.v_ledger_rows to authenticated;

-- ===== 20260926000004_stock_engine.sql =====
-- Stock engine and write API.
--
-- Layout:
--   _private helpers (prefixed with "_") do the work and take the acting user
--   as a parameter so the seed script can reuse them.
--   Public RPCs check who is calling, then delegate to a helper.
--
-- Every RPC runs in one transaction (PostgREST wraps each call), so any
-- RAISE rolls back everything the call did.
--
-- Error codes: PostgREST turns SQLSTATE 'PTxyz' into HTTP status xyz, and
-- supabase-js exposes the message as error.message.
--   PT400 bad input · PT401 not signed in · PT403 not allowed
--   PT404 not found · PT409 conflict (state, stock, duplicate)

-- ---------------------------------------------------------------------------
-- Caller checks
-- ---------------------------------------------------------------------------
create function public._require_user()
returns public.profiles
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v public.profiles;
begin
  select * into v from public.profiles where id = auth.uid();
  if not found then
    raise exception using errcode = 'PT401', message = 'Please sign in to continue.';
  end if;
  if not v.active then
    raise exception using errcode = 'PT403', message = 'Your account has been deactivated.';
  end if;
  return v;
end;
$$;

create function public._require_manager()
returns public.profiles
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v public.profiles := public._require_user();
begin
  if v.role <> 'MANAGER' then
    raise exception using errcode = 'PT403', message = 'Only inventory managers can do this.';
  end if;
  return v;
end;
$$;

-- ---------------------------------------------------------------------------
-- Lookups
-- ---------------------------------------------------------------------------
create function public._virtual_location(p_type public.location_type)
returns bigint
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_id bigint;
begin
  select id into v_id from public.locations where type = p_type and warehouse_id is null;
  if v_id is null then
    raise exception using errcode = 'PT409', message = format('Virtual location %s is missing', p_type);
  end if;
  return v_id;
end;
$$;

-- A real location, given either directly or as "the default location of a warehouse".
create function public._internal_location(p_location_id bigint, p_warehouse_id bigint, p_what text)
returns bigint
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_id bigint;
begin
  if p_location_id is not null then
    select id into v_id from public.locations
    where id = p_location_id and type = 'INTERNAL' and active;
    if v_id is null then
      raise exception using errcode = 'PT400', message = format('%s location not found', p_what);
    end if;
  elsif p_warehouse_id is not null then
    select l.id into v_id
    from public.locations l
    join public.warehouses w on w.id = l.warehouse_id
    where l.warehouse_id = p_warehouse_id and l.is_default and l.active and w.active;
    if v_id is null then
      raise exception using errcode = 'PT400', message = format('%s warehouse not found', p_what);
    end if;
  else
    raise exception using errcode = 'PT400', message = format('Choose a %s warehouse', lower(p_what));
  end if;
  return v_id;
end;
$$;

-- Accepts an id or a name/code (the Add Product modal sends names).
create function public._resolve_warehouse(p_id bigint, p_name text)
returns bigint
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_id bigint;
begin
  if p_id is not null then
    select id into v_id from public.warehouses where id = p_id;
  elsif nullif(trim(p_name), '') is not null then
    select id into v_id from public.warehouses
    where lower(name) = lower(trim(p_name)) or upper(code) = upper(trim(p_name));
  else
    return null;
  end if;
  if v_id is null then
    raise exception using errcode = 'PT400', message = format('Warehouse "%s" not found', coalesce(p_name, p_id::text));
  end if;
  return v_id;
end;
$$;

create function public._resolve_category(p_id bigint, p_name text)
returns bigint
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_id bigint;
begin
  if p_id is not null then
    select id into v_id from public.categories where id = p_id;
  elsif nullif(trim(p_name), '') is not null then
    select id into v_id from public.categories where lower(name) = lower(trim(p_name));
  else
    raise exception using errcode = 'PT400', message = 'Choose a category';
  end if;
  if v_id is null then
    raise exception using errcode = 'PT400', message = format('Category "%s" not found', coalesce(p_name, p_id::text));
  end if;
  return v_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Document numbers: PO-2026-0001, DO-..., TR-..., ADJ-...
-- The UPDATE row lock serialises concurrent callers, so numbers never repeat.
-- ---------------------------------------------------------------------------
create function public._next_reference(p_type public.operation_type, p_at timestamptz)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_prefix text := case p_type
    when 'RECEIPT' then 'PO' when 'DELIVERY' then 'DO'
    when 'TRANSFER' then 'TR' else 'ADJ' end;
  v_year int := extract(year from p_at at time zone public.app_time_zone())::int;
  v_n int;
begin
  insert into public.reference_sequences (prefix, year) values (v_prefix, v_year)
  on conflict do nothing;

  update public.reference_sequences
  set next_value = next_value + 1
  where prefix = v_prefix and year = v_year
  returning next_value - 1 into v_n;

  return format('%s-%s-%s', v_prefix, v_year, lpad(v_n::text, 4, '0'));
end;
$$;

-- ---------------------------------------------------------------------------
-- Quant locking and the single place where stock changes
-- ---------------------------------------------------------------------------

-- Make sure the quant row exists, then lock it. Returns the quantity on hand.
create function public._lock_quant(p_product_id bigint, p_location_id bigint)
returns numeric
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_qty numeric;
begin
  insert into public.stock_quants (product_id, location_id, quantity)
  values (p_product_id, p_location_id, 0)
  on conflict do nothing;

  select quantity into v_qty
  from public.stock_quants
  where product_id = p_product_id and location_id = p_location_id
  for update;

  return v_qty;
end;
$$;

-- Moves stock and writes the ledger row. Callers must already hold the locks
-- (see _validate_operation) so that locks are always taken in the same order.
create function public._apply_move(
  p_product_id bigint,
  p_source_id bigint,
  p_destination_id bigint,
  p_quantity numeric,
  p_move_type public.move_type,
  p_reference text,
  p_operation_id bigint,
  p_line_id bigint,
  p_user_id uuid,
  p_user_name text,
  p_at timestamptz
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_source public.v_locations;
  v_destination public.v_locations;
  v_available numeric;
  v_sku text;
begin
  if p_quantity is null or p_quantity <= 0 then
    return;
  end if;

  select * into v_source from public.v_locations where id = p_source_id;
  select * into v_destination from public.v_locations where id = p_destination_id;

  if v_source.type = 'INTERNAL' then
    v_available := public._lock_quant(p_product_id, p_source_id);
    if v_available < p_quantity then
      select sku into v_sku from public.products where id = p_product_id;
      raise exception using errcode = 'PT409', message = format(
        'Not enough stock for %s at %s: %s available, %s requested',
        v_sku, v_source.label, trim_scale(v_available), trim_scale(p_quantity));
    end if;
    update public.stock_quants
    set quantity = quantity - p_quantity, updated_at = p_at
    where product_id = p_product_id and location_id = p_source_id;
  end if;

  if v_destination.type = 'INTERNAL' then
    perform public._lock_quant(p_product_id, p_destination_id);
    update public.stock_quants
    set quantity = quantity + p_quantity, updated_at = p_at
    where product_id = p_product_id and location_id = p_destination_id;
  end if;

  insert into public.stock_moves (
    operation_id, operation_line_id, product_id, source_location_id, destination_location_id,
    quantity, move_type, reference, performed_by, performed_by_name, performed_at)
  values (
    p_operation_id, p_line_id, p_product_id, p_source_id, p_destination_id,
    p_quantity, p_move_type, p_reference, p_user_id, coalesce(p_user_name, ''), p_at);
end;
$$;

-- READY if every line can be served from the source location, otherwise WAITING.
-- Receipts and adjustments are always READY (nothing leaves a real location up front).
create function public._availability_state(p_operation_id bigint)
returns public.operation_state
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_op public.operations;
begin
  select * into v_op from public.operations where id = p_operation_id;
  if v_op.type in ('RECEIPT', 'ADJUSTMENT') then
    return 'READY';
  end if;

  if exists (
    select 1
    from public.operation_lines ln
    left join public.stock_quants q
      on q.product_id = ln.product_id and q.location_id = v_op.source_location_id
    where ln.operation_id = p_operation_id
      and ln.quantity > coalesce(q.quantity, 0)
  ) then
    return 'WAITING';
  end if;
  return 'READY';
end;
$$;

-- ---------------------------------------------------------------------------
-- Operation documents
-- ---------------------------------------------------------------------------

-- Where stock comes from and goes to, per document type.
create function public._operation_locations(
  p_type public.operation_type,
  p_payload jsonb,
  out o_source bigint,
  out o_destination bigint
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  case p_type
    when 'RECEIPT' then       -- Vendor -> Internal
      o_source := public._virtual_location('VENDOR');
      o_destination := public._internal_location(
        (p_payload ->> 'locationId')::bigint, (p_payload ->> 'warehouseId')::bigint, 'Destination');
    when 'DELIVERY' then      -- Internal -> Customer
      o_source := public._internal_location(
        (p_payload ->> 'locationId')::bigint, (p_payload ->> 'warehouseId')::bigint, 'Source');
      o_destination := public._virtual_location('CUSTOMER');
    when 'TRANSFER' then      -- Internal -> Internal
      o_source := public._internal_location(
        (p_payload ->> 'sourceLocationId')::bigint, (p_payload ->> 'sourceWarehouseId')::bigint, 'Source');
      o_destination := public._internal_location(
        (p_payload ->> 'destinationLocationId')::bigint, (p_payload ->> 'destinationWarehouseId')::bigint, 'Destination');
      if o_source = o_destination then
        raise exception using errcode = 'PT400', message = 'Source and destination must be different locations';
      end if;
    when 'ADJUSTMENT' then    -- Internal <-> Inventory adjustment (direction decided on validation)
      o_source := public._internal_location(
        (p_payload ->> 'locationId')::bigint, (p_payload ->> 'warehouseId')::bigint, 'Adjustment');
      o_destination := public._virtual_location('INVENTORY_LOSS');
  end case;
end;
$$;

create function public._insert_lines(p_operation_id bigint, p_type public.operation_type, p_lines jsonb)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_line jsonb;
  v_product_id bigint;
  v_qty numeric;
begin
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception using errcode = 'PT400', message = 'Add at least one product line';
  end if;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_product_id := (v_line ->> 'productId')::bigint;
    if not exists (select 1 from public.products where id = v_product_id and not archived) then
      raise exception using errcode = 'PT400', message = 'Unknown or archived product on a line';
    end if;

    begin
      if p_type = 'ADJUSTMENT' then
        v_qty := (v_line ->> 'countedQuantity')::numeric;
        if v_qty is null or v_qty < 0 then
          raise exception using errcode = 'PT400', message = 'Counted quantity must be zero or more';
        end if;
        insert into public.operation_lines (operation_id, product_id, quantity, counted_quantity)
        values (p_operation_id, v_product_id, 0, v_qty);
      else
        v_qty := (v_line ->> 'quantity')::numeric;
        if v_qty is null or v_qty <= 0 then
          raise exception using errcode = 'PT400', message = 'Quantity must be greater than zero';
        end if;
        insert into public.operation_lines (operation_id, product_id, quantity)
        values (p_operation_id, v_product_id, v_qty);
      end if;
    exception when unique_violation then
      raise exception using errcode = 'PT400', message = 'Each product can appear only once per document';
    end;
  end loop;
end;
$$;

create function public._create_operation(
  p_type public.operation_type,
  p_payload jsonb,
  p_user_id uuid,
  p_at timestamptz default now()
)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_locations record;
  v_responsible uuid := coalesce((p_payload ->> 'responsibleId')::uuid, p_user_id);
  v_id bigint;
begin
  select * into v_locations from public._operation_locations(p_type, p_payload);

  insert into public.operations (
    reference, type, state, source_location_id, destination_location_id,
    partner_name, reason, notes, scheduled_date,
    responsible_id, responsible_name, created_by, created_at, updated_at)
  values (
    public._next_reference(p_type, p_at), p_type, 'DRAFT',
    v_locations.o_source, v_locations.o_destination,
    coalesce(trim(p_payload ->> 'partnerName'), ''),
    coalesce(trim(p_payload ->> 'reason'), ''),
    coalesce(trim(p_payload ->> 'notes'), ''),
    nullif(p_payload ->> 'scheduledDate', '')::date,
    v_responsible,
    coalesce((select full_name from public.profiles where id = v_responsible),
             nullif(p_payload ->> 'responsibleName', ''), ''),
    p_user_id, p_at, p_at)
  returning id into v_id;

  perform public._insert_lines(v_id, p_type, p_payload -> 'lines');
  return v_id;
end;
$$;

create function public._lock_operation(p_operation_id bigint)
returns public.operations
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_op public.operations;
begin
  select * into v_op from public.operations where id = p_operation_id for update;
  if not found then
    raise exception using errcode = 'PT404', message = 'Document not found';
  end if;
  return v_op;
end;
$$;

create function public._update_operation(p_operation_id bigint, p_payload jsonb)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_op public.operations := public._lock_operation(p_operation_id);
  v_locations record;
  v_responsible uuid;
begin
  if v_op.state in ('DONE', 'CANCELLED') then
    raise exception using errcode = 'PT409', message = format(
      '%s is %s and can no longer be edited', v_op.reference, lower(public.status_label(v_op.state)));
  end if;

  select * into v_locations from public._operation_locations(v_op.type, p_payload);
  v_responsible := coalesce((p_payload ->> 'responsibleId')::uuid, v_op.responsible_id);

  update public.operations set
    source_location_id      = v_locations.o_source,
    destination_location_id = v_locations.o_destination,
    partner_name            = coalesce(trim(p_payload ->> 'partnerName'), partner_name),
    reason                  = coalesce(trim(p_payload ->> 'reason'), reason),
    notes                   = coalesce(trim(p_payload ->> 'notes'), notes),
    scheduled_date          = case when p_payload ? 'scheduledDate'
                                   then nullif(p_payload ->> 'scheduledDate', '')::date
                                   else scheduled_date end,
    responsible_id          = v_responsible,
    responsible_name        = coalesce((select full_name from public.profiles where id = v_responsible), responsible_name)
  where id = p_operation_id;

  if p_payload ? 'lines' then
    delete from public.operation_lines where operation_id = p_operation_id;
    perform public._insert_lines(p_operation_id, v_op.type, p_payload -> 'lines');
  end if;

  -- A confirmed document is re-checked against current stock.
  if v_op.state in ('WAITING', 'READY') then
    update public.operations set state = public._availability_state(p_operation_id)
    where id = p_operation_id;
  end if;
  return p_operation_id;
end;
$$;

create function public._confirm_operation(p_operation_id bigint)
returns public.operation_state
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_op public.operations := public._lock_operation(p_operation_id);
  v_state public.operation_state;
begin
  if v_op.state <> 'DRAFT' then
    raise exception using errcode = 'PT409', message = format(
      'Only pending drafts can be confirmed (%s is %s)', v_op.reference, lower(v_op.state::text));
  end if;
  v_state := public._availability_state(p_operation_id);
  update public.operations set state = v_state where id = p_operation_id;
  return v_state;
end;
$$;

create function public._check_availability(p_operation_id bigint)
returns public.operation_state
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_op public.operations := public._lock_operation(p_operation_id);
  v_state public.operation_state;
begin
  if v_op.state not in ('WAITING', 'READY') then
    raise exception using errcode = 'PT409', message = format(
      'Availability can only be checked on confirmed documents (%s is %s)', v_op.reference, lower(v_op.state::text));
  end if;
  v_state := public._availability_state(p_operation_id);
  update public.operations set state = v_state where id = p_operation_id;
  return v_state;
end;
$$;

create function public._cancel_operation(p_operation_id bigint)
returns public.operation_state
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_op public.operations := public._lock_operation(p_operation_id);
begin
  if v_op.state in ('DONE', 'CANCELLED') then
    raise exception using errcode = 'PT409', message = format(
      '%s is already %s', v_op.reference, lower(public.status_label(v_op.state)));
  end if;
  update public.operations set state = 'CANCELLED' where id = p_operation_id;
  return 'CANCELLED';
end;
$$;

-- The heart of the engine. Moves stock for a READY document and marks it DONE.
--   p_lines: optional [{lineId, doneQuantity}] for partial validation
--   p_create_backorder: put the undelivered remainder on a new document
--   p_can_signoff: whether the caller may approve stock-reducing adjustments
-- Returns the backorder's id, or null.
create function public._validate_operation(
  p_operation_id bigint,
  p_user_id uuid,
  p_lines jsonb,
  p_create_backorder boolean,
  p_can_signoff boolean,
  p_at timestamptz default now()
)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_op public.operations := public._lock_operation(p_operation_id);
  v_user_name text;
  v_line jsonb;
  v_row record;
  v_ln public.operation_lines;
  v_system numeric;
  v_diff numeric;
  v_needs_signoff boolean;
  v_backorder_id bigint;
begin
  if v_op.state <> 'READY' then
    raise exception using errcode = 'PT409', message = format(
      'Only documents that are Ready can be validated (%s is %s)', v_op.reference, lower(v_op.state::text));
  end if;

  v_user_name := coalesce((select full_name from public.profiles where id = p_user_id), v_op.responsible_name, '');

  -- 1. Decide how much of each line is being done.
  if v_op.type <> 'ADJUSTMENT' then
    if p_lines is not null and jsonb_typeof(p_lines) = 'array' then
      for v_line in select * from jsonb_array_elements(p_lines) loop
        update public.operation_lines
        set done_quantity = (v_line ->> 'doneQuantity')::numeric
        where id = (v_line ->> 'lineId')::bigint and operation_id = p_operation_id;
        if not found then
          raise exception using errcode = 'PT400', message = 'A line does not belong to this document';
        end if;
      end loop;
    else
      update public.operation_lines set done_quantity = quantity where operation_id = p_operation_id;
    end if;

    if not exists (select 1 from public.operation_lines where operation_id = p_operation_id and done_quantity > 0) then
      raise exception using errcode = 'PT400', message = 'Nothing to validate: every done quantity is zero';
    end if;
  end if;

  -- 2. Lock every quant this document touches, always in (product, location)
  --    order, so two validations can never deadlock each other.
  for v_row in
    select ln.product_id, loc.id as location_id
    from public.operation_lines ln
    cross join (values (v_op.source_location_id), (v_op.destination_location_id)) as loc (id)
    join public.locations l on l.id = loc.id and l.type = 'INTERNAL'
    where ln.operation_id = p_operation_id
    order by ln.product_id, loc.id
  loop
    perform public._lock_quant(v_row.product_id, v_row.location_id);
  end loop;

  -- 3. Move the stock.
  if v_op.type = 'ADJUSTMENT' then
    v_needs_signoff := not p_can_signoff
      and coalesce((select require_signoff_negative_adjustments from public.app_settings where id = 1), true);

    for v_ln in select * from public.operation_lines where operation_id = p_operation_id order by id loop
      select quantity into v_system from public.stock_quants
      where product_id = v_ln.product_id and location_id = v_op.source_location_id;
      v_diff := v_ln.counted_quantity - v_system;

      if v_diff < 0 and v_needs_signoff then
        raise exception using errcode = 'PT403',
          message = 'Manager sign-off is required for adjustments that reduce stock';
      end if;

      update public.operation_lines
      set system_quantity = v_system, quantity = abs(v_diff), done_quantity = abs(v_diff)
      where id = v_ln.id;

      if v_diff < 0 then
        perform public._apply_move(v_ln.product_id, v_op.source_location_id, v_op.destination_location_id,
          -v_diff, 'ADJUSTMENT', v_op.reference, p_operation_id, v_ln.id, p_user_id, v_user_name, p_at);
      elsif v_diff > 0 then
        perform public._apply_move(v_ln.product_id, v_op.destination_location_id, v_op.source_location_id,
          v_diff, 'ADJUSTMENT', v_op.reference, p_operation_id, v_ln.id, p_user_id, v_user_name, p_at);
      end if;
    end loop;
  else
    for v_ln in
      select * from public.operation_lines
      where operation_id = p_operation_id and done_quantity > 0
      order by id
    loop
      perform public._apply_move(v_ln.product_id, v_op.source_location_id, v_op.destination_location_id,
        v_ln.done_quantity, v_op.type::text::public.move_type, v_op.reference,
        p_operation_id, v_ln.id, p_user_id, v_user_name, p_at);
    end loop;

    -- 4. Optional backorder for whatever was not done.
    if p_create_backorder and exists (
      select 1 from public.operation_lines
      where operation_id = p_operation_id and done_quantity < quantity
    ) then
      insert into public.operations (
        reference, type, state, source_location_id, destination_location_id,
        partner_name, reason, notes, scheduled_date, responsible_id, responsible_name,
        created_by, backorder_of_id, created_at, updated_at)
      values (
        public._next_reference(v_op.type, p_at), v_op.type, 'DRAFT',
        v_op.source_location_id, v_op.destination_location_id,
        v_op.partner_name, v_op.reason, v_op.notes, v_op.scheduled_date,
        v_op.responsible_id, v_op.responsible_name, p_user_id, p_operation_id, p_at, p_at)
      returning id into v_backorder_id;

      insert into public.operation_lines (operation_id, product_id, quantity)
      select v_backorder_id, product_id, quantity - done_quantity
      from public.operation_lines
      where operation_id = p_operation_id and done_quantity < quantity;

      update public.operations
      set state = public._availability_state(v_backorder_id)
      where id = v_backorder_id;
    end if;
  end if;

  update public.operations set state = 'DONE', validated_at = p_at where id = p_operation_id;
  return v_backorder_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Products
-- ---------------------------------------------------------------------------
create function public._create_product(
  p_name text,
  p_sku text,
  p_category text,
  p_category_id bigint,
  p_initial_stock numeric,
  p_warehouse text,
  p_warehouse_id bigint,
  p_price numeric,
  p_min_stock numeric,
  p_unit text,
  p_reorder_qty numeric,
  p_user_id uuid,
  p_at timestamptz default now()
)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_category_id bigint := public._resolve_category(p_category_id, p_category);
  v_warehouse_id bigint := public._resolve_warehouse(p_warehouse_id, p_warehouse);
  v_sku text := upper(trim(coalesce(p_sku, '')));
  v_prefix text;
  v_product_id bigint;
  v_location_id bigint;
  v_initial numeric := coalesce(p_initial_stock, 0);
begin
  if nullif(trim(p_name), '') is null then
    raise exception using errcode = 'PT400', message = 'Product name is required';
  end if;
  if v_initial < 0 then
    raise exception using errcode = 'PT400', message = 'Initial stock cannot be negative';
  end if;
  if coalesce(p_price, 0) < 0 then
    raise exception using errcode = 'PT400', message = 'Price cannot be negative';
  end if;
  if coalesce(p_min_stock, 0) < 0 then
    raise exception using errcode = 'PT400', message = 'Minimum stock cannot be negative';
  end if;

  -- Blank SKU: generate one from the category, e.g. ELE-000042.
  if v_sku = '' then
    select upper(left(regexp_replace(name, '[^A-Za-z]', '', 'g'), 3)) into v_prefix
    from public.categories where id = v_category_id;
    v_prefix := coalesce(nullif(v_prefix, ''), 'PRD');
    loop
      v_sku := v_prefix || '-' || lpad(nextval('public.product_sku_seq')::text, 6, '0');
      exit when not exists (select 1 from public.products where upper(sku) = v_sku);
    end loop;
  elsif exists (select 1 from public.products where upper(sku) = v_sku) then
    raise exception using errcode = 'PT409', message = format('SKU %s already exists', v_sku);
  end if;

  if v_warehouse_id is null and v_initial > 0 then
    v_warehouse_id := (select default_warehouse_id from public.app_settings where id = 1);
    if v_warehouse_id is null then
      raise exception using errcode = 'PT400', message = 'Choose a warehouse for the initial stock';
    end if;
  end if;

  insert into public.products (name, sku, category_id, unit, price, primary_warehouse_id, created_at, updated_at)
  values (p_name, v_sku, v_category_id, coalesce(nullif(trim(p_unit), ''), 'pcs'),
          coalesce(p_price, 0), v_warehouse_id, p_at, p_at)
  returning id into v_product_id;

  insert into public.reorder_rules (product_id, min_qty, reorder_qty)
  values (v_product_id, coalesce(p_min_stock, 0), p_reorder_qty);

  -- Opening balance goes through the ledger like any other stock change.
  if v_initial > 0 then
    v_location_id := public._internal_location(null, v_warehouse_id, 'Initial stock');
    perform public._lock_quant(v_product_id, v_location_id);
    perform public._apply_move(v_product_id, public._virtual_location('INVENTORY_LOSS'), v_location_id,
      v_initial, 'INITIAL', 'INIT-' || v_sku, null, null, p_user_id,
      coalesce((select full_name from public.profiles where id = p_user_id), ''), p_at);
  end if;

  return v_product_id;
end;
$$;

create function public.create_product(
  p_name text,
  p_sku text default null,
  p_category text default null,
  p_category_id bigint default null,
  p_initial_stock numeric default 0,
  p_warehouse text default null,
  p_warehouse_id bigint default null,
  p_price numeric default 0,
  p_min_stock numeric default 0,
  p_unit text default 'pcs',
  p_reorder_qty numeric default null
)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user public.profiles := public._require_manager();
begin
  return public._create_product(p_name, p_sku, p_category, p_category_id, p_initial_stock,
    p_warehouse, p_warehouse_id, p_price, p_min_stock, p_unit, p_reorder_qty, v_user.id, now());
end;
$$;

-- p_payload keys (all optional): name, sku, categoryId | category, price, minStock,
-- reorderQty, unit, warehouseId | warehouse
create function public.update_product(p_id bigint, p_payload jsonb)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user public.profiles := public._require_manager();
  v_sku text := upper(trim(p_payload ->> 'sku'));
begin
  if not exists (select 1 from public.products where id = p_id) then
    raise exception using errcode = 'PT404', message = 'Product not found';
  end if;
  if v_sku is not null and exists (select 1 from public.products where upper(sku) = v_sku and id <> p_id) then
    raise exception using errcode = 'PT409', message = format('SKU %s already exists', v_sku);
  end if;
  if (p_payload ->> 'price')::numeric < 0 or (p_payload ->> 'minStock')::numeric < 0 then
    raise exception using errcode = 'PT400', message = 'Price and minimum stock cannot be negative';
  end if;

  update public.products set
    name        = coalesce(nullif(trim(p_payload ->> 'name'), ''), name),
    sku         = coalesce(nullif(v_sku, ''), sku),
    category_id = case when p_payload ? 'categoryId' or p_payload ? 'category'
                       then public._resolve_category((p_payload ->> 'categoryId')::bigint, p_payload ->> 'category')
                       else category_id end,
    price       = coalesce((p_payload ->> 'price')::numeric, price),
    unit        = coalesce(nullif(trim(p_payload ->> 'unit'), ''), unit),
    primary_warehouse_id = case when p_payload ? 'warehouseId' or p_payload ? 'warehouse'
                       then public._resolve_warehouse((p_payload ->> 'warehouseId')::bigint, p_payload ->> 'warehouse')
                       else primary_warehouse_id end
  where id = p_id;

  if p_payload ? 'minStock' or p_payload ? 'reorderQty' then
    insert into public.reorder_rules (product_id, min_qty, reorder_qty)
    values (p_id, coalesce((p_payload ->> 'minStock')::numeric, 0), (p_payload ->> 'reorderQty')::numeric)
    on conflict (product_id) do update set
      min_qty     = coalesce((p_payload ->> 'minStock')::numeric, public.reorder_rules.min_qty),
      reorder_qty = case when p_payload ? 'reorderQty' then (p_payload ->> 'reorderQty')::numeric
                         else public.reorder_rules.reorder_qty end;
  end if;
  return p_id;
end;
$$;

-- Products are archived, never deleted, so their history stays intact.
create function public.set_product_archived(p_id bigint, p_archived boolean)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user public.profiles := public._require_manager();
begin
  update public.products set archived = p_archived where id = p_id;
  if not found then
    raise exception using errcode = 'PT404', message = 'Product not found';
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- Warehouses and locations
-- ---------------------------------------------------------------------------
create function public._create_warehouse(p_name text, p_code text, p_address text, p_capacity_units numeric)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id bigint;
begin
  if nullif(trim(p_name), '') is null or nullif(trim(p_code), '') is null then
    raise exception using errcode = 'PT400', message = 'Warehouse name and code are required';
  end if;
  if exists (select 1 from public.warehouses where lower(name) = lower(trim(p_name))) then
    raise exception using errcode = 'PT409', message = format('A warehouse named "%s" already exists', trim(p_name));
  end if;
  if exists (select 1 from public.warehouses where upper(code) = upper(trim(p_code))) then
    raise exception using errcode = 'PT409', message = format('Warehouse code %s is already used', upper(trim(p_code)));
  end if;

  insert into public.warehouses (name, code, address, capacity_units)
  values (trim(p_name), upper(trim(p_code)), coalesce(trim(p_address), ''), p_capacity_units)
  returning id into v_id;

  -- Every warehouse gets a default location so documents can just name the warehouse.
  insert into public.locations (warehouse_id, name, code, type, is_default)
  values (v_id, 'Stock', upper(trim(p_code)) || '/STOCK', 'INTERNAL', true);
  return v_id;
end;
$$;

create function public.create_warehouse(
  p_name text,
  p_code text,
  p_address text default '',
  p_capacity_units numeric default null
)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user public.profiles := public._require_manager();
begin
  return public._create_warehouse(p_name, p_code, p_address, p_capacity_units);
end;
$$;

create function public._create_location(p_warehouse_id bigint, p_name text, p_code text)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_wh public.warehouses;
  v_id bigint;
begin
  select * into v_wh from public.warehouses where id = p_warehouse_id;
  if not found then
    raise exception using errcode = 'PT404', message = 'Warehouse not found';
  end if;
  if nullif(trim(p_name), '') is null then
    raise exception using errcode = 'PT400', message = 'Location name is required';
  end if;
  if exists (select 1 from public.locations where warehouse_id = p_warehouse_id and lower(name) = lower(trim(p_name))) then
    raise exception using errcode = 'PT409', message = format('%s already has a location named "%s"', v_wh.name, trim(p_name));
  end if;

  insert into public.locations (warehouse_id, name, code, type)
  values (p_warehouse_id, trim(p_name),
          coalesce(nullif(upper(trim(p_code)), ''),
                   v_wh.code || '/' || upper(regexp_replace(trim(p_name), '\s+', '-', 'g'))),
          'INTERNAL')
  returning id into v_id;
  return v_id;
end;
$$;

create function public.create_location(p_warehouse_id bigint, p_name text, p_code text default null)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user public.profiles := public._require_manager();
begin
  return public._create_location(p_warehouse_id, p_name, p_code);
end;
$$;

